def find_kth(arr1, arr2, n1, n2, k):
    """
    Finds the kth element in two sorted arrays.
    """
    if n1 > n2:
        return find_kth(arr2, arr1, n2, n1, k)  # Ensure arr1 is the smaller array

    if k == 1:
        return min(arr1[0], arr2[0])

    i = n1 // 2
    j = k // 2

    if arr1[i] <= arr2[j]:
        return find_kth(arr1[i+1:], arr2, n1 - (i+1), n2, k - (i+1))
    else:
        return find_kth(arr1, arr2[j+1:], n1, n2 - (j+1), k - (j+1))
