def find_kth(A, B, i, startA, endA, startB, endB):
    # Case 0: A is exhausted
    if startA > endA:
        return B[startB + i - 1]

    # Case 1: B is exhausted
    elif startB > endB:
        return A[startA + i - 1]

    # When both arrays are not exhausted
    midA = (startA + endA) // 2
    midB = (startB + endB) // 2

    # Compare the first elements of A and B and move pointers
    if A[midA] > B[midB]:
        return find_kth(A, B, i - midA - 1, startA, midA - 1, startB, endB)
    else:
        return find_kth(A, B, i - midB - 1, startA, endA, startB + midB + 1, endB)
