from bisect import bisect_left

def find_platform(arrival, departure, n):
    departure.sort()
    platforms = 1
    min_platforms_required = 1

    for i in range(1, n):
        index = bisect_left(departure, arrival[i])
        if index < n and departure[index] <= arrival[i]:
