def find_first_occurrence(arr, num):
    index = -1  # Initialize index to -1 to indicate if the number is not found
    left, right = 0, len(arr) - 1  # Initialize pointers for binary search

    while left <= right:
        mid = (left + right) // 2  # Calculate the middle index

        if arr[mid] == num:
            index = mid  # If the number is found, update the index and move the right pointer
            right = mid - 1
        elif arr[mid] < num:
            left = mid + 1  # If the number is greater, move the left pointer to the right
        else:
            right = mid - 1  # If the number is smaller, move the right pointer to the left

