    low, high = 0, len(arr) - 1
    result = -1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == x:
            result = mid
            high = mid - 1  # Move left to find the first occurrence
        elif arr[mid] < x:
            low = mid + 1
        else:
            high = mid - 1
    return result
