def sum_Of_Subarray_Prod(nums, n):
    # First calculate the prefixproduct
    pre = [0]*n
    pre[0] = nums[0]
    for i in range(1,n):
        pre[i] = pre[i-1]*nums[i]

    # Initialize the sum to 0
    sm_sum = 0
    # Iterate over the array to calculate the sum of products of all subarrays
    for i in range(n):
        for j in range(i,n):
            if i==j:
                sm_sum += nums[i]
            else:
                sm_sum += pre[j]-pre[i-1]
    return sm_sum
```

