    # For n=1, there's only 1 way to tile (a 1x1 square)
    if n == 1:
        return 1
    # For n=2, there's 2 ways to tile (a 1x2 rectangle or 2x1 rectangle)
    elif n == 2:
        return 2
    # For other numbers, we can calculate the ways to tile using the recurrence relation T(n) = T(n-1) + T(n-2)
    else:
        return get_noOfways(n-1) + get_noOfways(n-2)
