def get_noOfways(n):
    # Dynamic programming solution for tiling problem
    # Base cases
    if n == 0:
        return 0  # No ways to tile if the number of tiles is 0
    elif n == 1:
        return 1  # One way to tile with one tile
    elif n == 2:
        return 2  # Two ways to tile with two tiles (two ways with two-unit tiles and one way with four-unit tile)

    # Array to store solutions of subproblems
    dp = [0] * (n + 1)
    dp[0] = 0
    dp[1] = 1
    dp[2] = 2

    # Fill the dp array
    for i in range(3, n + 1):
        dp[i] = dp[i - 1] + dp[i - 2]

    return dp[n]
```

