def sum_Square(num):
    i = 0
    while i*i <= num:
        if num % i == 0:
            x = num // i
            if x*x + i*i == num:
                return True
            if x//i != i:
                if (num//(x//i))**2 + i*i == num:
                    return True
        i += 1
    return False
