def count_Fac(n):
    # Initialize a set to store distinct prime factors
    prime_factors = set()

    # Remove the factor 2 as it is a unit power
    while n % 2 == 0:
        prime_factors.add(2)
        n //= 2

    # Test for odd factors from 3 to the square root of n
    for i in range(3, int(n**0.5) + 1, 2):
        while n % i == 0:
            prime_factors.add(i)
            n //= i

    # If n is a prime number greater than 2
    if n > 2:
        prime_factors.add(n)

    # Return the count of distinct prime factors
    return len(prime_factors)
