import math

def dealnnoy_num(n, k):
    # Initialize the first two delannoy numbers
    if n == 0:
        return 1
    elif k == 0:
        return 1
    elif k == n:
        return math.comb(n, 1)

    # Calculate the delannoy number using the recursive formula
    return dealnnoy_num(n-1, k) + dealnnoy_num(n-1, k-1)
