def check_min_heap(data, index):
    size = len(data)
    # checks if the current node and its children violate the min heap property
    if index * 2 + 1 < size and data[index] > data[index * 2 + 1]:
        return False
    if index * 2 + 2 < size and data[index] > data[index * 2 + 2]:
        return False
    # recursively checks the left and right subtrees
    return check_min_heap(data, index * 2 + 1) and check_min_heap(data, index * 2 + 2)
