def check_min_heap(tree, i):
    # Check if the left child index is within bounds
    if (2 * i) + 1 < len(tree):
        # If left child is greater than root, return False
        if tree[(2 * i) + 1] > tree[i]:
            return False
        # Recursively check the left subtree
        if not check_min_heap(tree, (2 * i) + 1):
            return False

    # Check if the right child index is within bounds
    if (2 * i) + 2 < len(tree):
        # If right child is greater than root, return False
        if tree[(2 * i) + 2] > tree[i]:
            return False
        # Recursively check the right subtree
        if not check_min_heap(tree, (2 * i) + 2):
            return False

    # If both conditions are met, return True
    return True
```

