def check_min_heap(array, root):
    n = len(array)
    if not array:
        return True
    left = 2 * root + 1
    right = 2 * root + 2
    if left < n and array[root] > array[left]:
        return False
    if right < n and array[root] > array[right]:
        return False
    return check_min_heap(array, left) and check_min_heap(array, right)
```

