def check_min_heap(arr, i):
    n = len(arr)
    while (2*i + 1) < n:
        child = 2*i + 1
        if child + 1 < n and arr[child + 1] < arr[child]:
            child += 1
        if arr[i] > arr[child]:
            arr[i], arr[child] = arr[child], arr[i]
        i = child
    return True
```

