def coin_change(coins, amount, sum):
    # Initialize the result matrix
    dp = [[0 for _ in range(sum + 1)] for _ in range(len(coins))]

    # Base case: there are 1 way to make sum 0 (by using 0 coins)
    for i in range(len(coins)):
        dp[i][0] = 1

    # Fill the dp table
    for i in range(1, len(coins)):
        for j in range(1, sum + 1):
            if j >= coins[i]:
                dp[i][j] = dp[i-1][j] + dp[i][j-coins[i]]
            else:
                dp[i][j] = dp[i-1][j]

    return dp[len(coins)-1][sum]
