def find_Max(nums, left, right):
    # Base case: when the search space is reduced to a single element
    if left == right:
        return nums[left]
    # Find the middle index
    mid = (left + right) // 2
    # Check if the middle element is the maximum
    if nums[mid] > nums[mid + 1]:
        return nums[mid]
    # If the element at the middle index is not the maximum, the maximum must be in the unsorted part of the array
    if nums[mid] > nums[left]:
        # If the element at the start is less than the element at the middle, the maximum must be in the right half
        return find_Max(nums, mid + 1, right)
    else:
        # If the element at the start is greater than the element at the middle, the maximum must be in the left half
        return find_Max(nums, left, mid)
```

