def modular_sum(arr, n, m):
    # Initialize a dynamic programming table
    dp = [[False] * (m + 1) for _ in range(n + 1)]

    # Base case: there is a zero-sum subset with sum 0
    for _ in range(n + 1):
        dp[_][0] = True

    # Fill the dp table
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if arr[i - 1] <= j:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - arr[i - 1]]
            else:
                dp[i][j] = dp[i - 1][j]

    # Check if there is a subset with sum divisible by m
    return dp[n][m]
```

