def modular_sum(arr, n, m, sum_required):
    # Initialize a 2D array to store intermediate results
    dp = [[False for _ in range(sum_required + 1)] for _ in range(n + 1)]

    # The 0-sum problem initialization: there is always a subset with sum 0 for any array
    dp[0][0] = True

    # Fill the dp table
    for i in range(1, n + 1):
        for j in range(sum_required + 1):
            if j < arr[i - 1]:
                dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - arr[i - 1]]

    # Check if there is a subset whose sum is divisible by m
    return dp[n][sum_required]
```

