def modular_sum(arr, n, m):
    total_sum = sum(arr)
    if total_sum % m == 0:
        return True
    remaining_sum = total_sum % m

    # Check if there is a subset with sum * 2 covering target sum
    for i in range(n):
        if (m - remaining_sum) % arr[i] == 0 and (m - (total_sum - arr[i])) % arr[i] == 0:
            return True
    return False
```

