def find_Digits(n):
    if n == 0 or n == 1:
        return 1
    factorial = 1
    for i in range(2, n + 1):
        factorial *= i
    digit_count = 0
    while factorial > 0:
        factorial //= 10
        digit_count += 1
    return digit_count
