def min_cost(cost, m, n):
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            cost[i][j] += min(cost[i - 1][j], cost[i][j - 1])  # Add the minimum cost from the cell above or the left cell
    return cost[m][n]  # The minimum cost path to (m, n) is in cost[m][n]
