def min_cost(cost_matrix, m, n):
    # Initialize visited array to keep track of visited positions
    visited = [[False for _ in range(m)] for _ in range(n)]
    # Function to recursively find the minimum cost to reach position (x, y)
    def dfs(x, y):
        if x == m - 1 and y == n - 1:
            return cost_matrix[x][y]
        visited[x][y] = True
        directions = [(0, 1), (1, 0)]  # Possible directions: right, down
        min_cost = float('inf')
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny]:
                min_cost = min(min_cost, dfs(nx, ny) + cost_matrix[x][y])
        visited[x][y] = False
        return min_cost
    # Start the DFS from the top-left corner
    return dfs(0, 0)
```

