def jacobsthal_num(n):
    # Base cases: jacobsthal_num(0) = 0, jacobsthal_num(1) = 1
    if n == 0:
        return 0
    elif n == 1:
        return 1
    # Recursive formula: jacobsthal_num(n) = 4 * jacobsthal_num(n-1) - jacobsthal_num(n-2)
    else:
        return 4 * jacobsthal_num(n-1) - jacobsthal_num(n-2)
```

