def find_triplet_array(array, sum_value, target_sum):
    array.sort()
    n = len(array)
    for i in range(n - 2):
        for j in range(i + 1, n - 1):
            left, right = j + 1, n - 1
            while left < right:
                current_sum = array[i] + array[j] + array[left] + array[right]
                if current_sum == target_sum:
                    return (array[i], array[j], array[left], array[right])
                elif current_sum < target_sum:
                    left += 1
                else:
                    right -= 1
    return None
```

