def check_prime(n):
    """Check if a number is prime."""
    return n > 1 and all(n % i != 0 for i in range(2, int(n**0.5) + 1))

def find_lcm(arr):
    """Calculate the least common multiple (LCM) of an array of numbers."""
    prime_factors = {}  # Dictionary to store prime factorization
    for num in arr:
        if check_prime(num):
            prime_factors[num] = prime_factors.get(num, 0) + 1  # Count prime factors
        else:
            for i in range(2, num + 1):
                while num % i == 0:
                    if i in prime_factors:
                        prime_factors[i] += 1
                    else:
                        prime_factors[i] = 1
                    num = num // i

    # Calculate LCM
    lcm = 1
    for prime, exp in prime_factors.items():
        lcm *= (prime ** exp)

    return lcm
```

