def Seq_Linear(seq):
    # Check if the sequence has a common difference between consecutive elements
    if len(seq) < 2:
        return "Not enough elements to check for linear sequence"
    common_diff = seq[1] - seq[0]
    for i in range(2, len(seq)):
        if seq[i] - seq[i-1] != common_diff:
            return "Non-linear Sequence"
    return "Linear Sequence"
