def min_jumps(nums, n):
    if n <= 1:
        return 0
    dp = [float('inf')] * n
    dp[0] = 0
    for i in range(1, n):
        for j in range(i):
            if j + nums[j] >= i:
                dp[i] = min(dp[i], dp[j] + 1)
    return dp[-1]
```

```python
def min_jumps(arr, n):
    if n <= 1:
        return 0
    if arr[0] == 0:
        return -1  # No jumps can be made
    jumps = arr[0]
    max_reach = arr[0]
    for i in range(1, n):
        max_reach = max(max_reach, i + arr[i])
        if i == jumps:
            jumps = max_reach  # Update the max jumps possible
            if jumps >= n - 1:
                break  # Reach the end directly
    if jumps < n - 1:
        return -1  # Not possible to reach the end
    return jumps
```

