def min_jumps(arr, n):
    if n <= 1:
        return 0

    jumps = [0] * n
    for i in range(1, n):
        if arr[i] == 0:
            jumps[i] = float('inf')
        else:
            min_jumps = float('.inf')
            for j in range(i):
                if arr[j] + j >= i:
                    min_jumps = min(min_jumps, jumps[j])
            if min_jumps != float('inf'):
                jumps[i] = min_jumps + 1

    return jumps[n-1]
```

