def is_polite(n):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    polite_number = 0
    num = 0

    while polite_number < n:
        num += 1
        if is_prime(num) and all(is_prime(i + num) for i in range(1, num // 2 + 1)):
            polite_number += 1

    return num
```

