def count_unique_sublists(items):
    """
    This function takes a list of lists and returns a dictionary with the count of unique lists.

    :param items: List of lists
    :return: Dictionary with unique lists as keys and their counts as values
    """
    unique_counts = {}
    for sublist in items:
        if tuple(sublist) in unique_counts:
            unique_counts[tuple(sublist)] += 1
        else:
            unique_counts[tuple(sublist)] = 1
    return unique_counts

