```python
def get_median(arr1, arr2, n):
    i = 0
    j = 0
    count = 0
    total = 0

    while i < n and j < n:
        if arr1[i] < arr2[j]:
            total += arr1[i]
            i += 1
        else:
            total += arr2[j]
            j += 1
        count += 1

        if count == n:
            if i < n:
                total += arr1[i]
            else:
                total += arr2[j]
            break

    # Since total has the sum of n elements, divide by 2 to get the median
    return total / 2.0
```

