def find_longest_conseq_subseq(nums, n):
    # Initialize a list to keep track of the longest sub-sequence end points
    lps = [1] * n
    # Sort the numbers to process consecutive elements
    nums.sort()

    # Build the longest sub-sequence end points
    for i in range(1, n):
        if nums[i] == nums[i-1] + 1:
            lps[i] = lps[i-1] + 1

    # The maximum value in lps represents the length of the longest sub-sequence
    return max(lps)
