    index_map = {num: idx for idx, num in enumerate(nums)}
    res = 0

    for i in range(n):
        j = index_map.get(nums[i] + 1)
        if j:
            while j in index_map:
                j = index_map.get(j + 1)
            res = max(res, j - i + 1)

