def find_longest_conseq_subseq(nums, N):
    # Initialize a list to keep track of the longest sub-sequence ending at each number
    dp = [1] * N

    # Iterate through the list to populate the dp list
    for i in range(1, N):
        for j in range(i):
            if nums[i] - nums[j] == 1:
                dp[i] = max(dp[i], dp[j] + 1)

    # The maximum value in dp represents the length of the longest consecutive sub-sequence
    return max(dp)
```

