def find_Min_Swaps(arr, swap_count):
    max_index = 0
    for i in range(1, len(arr)):
        if arr[i] > arr[max_index]:
            max_index = i

    # Sort the array except the part that is already sorted
    arr[0: max_index + 1] = sorted(arr[0: max_index + 1])
    arr[0: max_index + 1], arr[max_index] = arr[max_index], arr[0: max_index + 1]

    # Count the additional swaps required
    additional_swaps = 0
    for i in range(1, max_index + 1):
        if arr[i] < arr[i - 1]:
            additional_swaps += i - 1

    return swap_count + additional_swaps
