import heapq

def cheap_items(dataset, n):
    if not dataset:
        return []

    # Use a min heap to find the n cheapest items
    min_heap = []
    for item in dataset:
        heapq.heappush(min_heap, item)

    # Pop the n cheapest items from the heap
    cheapest.getItems = lambda: [heapq.heappop(min_heap) for _ in range(n)]
    return cheapest.getItems()
