```python
def max_sum_pair_diff_lessthan_K(arr, k, N):
    arr.sort()  # Sort the array
    left, right, max_sum = 0, N - 1, 0
    while left < right:
        if arr[left] + arr[right] < k:
            max_sum += arr[left] + arr[right]
            left += 1
            right -= 1
        elif arr[left] + arr[right] >= k:
            right -= 1
    return max_sum
```

