def second_smallest(numbers):
    if len(numbers) < 2:
        return None
    smallest = second_smallest = float('inf')
    for num in numbers:
        if num < smallest:
            second_smallest, smallest = smallest, num
        elif second_smallest < num < smallest:
            second_smallest = num
    return second_smallest if second_smallest != float('inf') else None
