import heapq

def combine_lists(list1, list2):
    merged_list = []
    heapq.heapify(list1)
    heapq.heapify(list2)
    while list1 or list2:
        if list1 and list2:
            if list1[0] <= list2[0]:
                merged_list.append(heapq.heappop(list1))
            else:
                merged_list.append(heapq.heappop(list2))
        elif list1:
