    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j]:
                increasing[i] = max(increasing[i], increasing[j] + 1)

    # Find the length of the longest decreasing subsequence
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if arr[i] > arr[j]:
                decreasing[i] = max(decreasing[i], decreasing[j] + 1)

    # The length of the longest bitonic subsequence is the maximum value in increasing array plus one minus the minimum value in decreasing array
    return max(increasing) + max(decreasing) - 1
