def maxAverageOfPath(matrix, n):
    def get_neighbors(i, j):
        neighbors = []
        if i > 0:
            neighbors.append((i-1, j))
        if i < n-1:
            neighbors.append((i+1, j))
        if j > 0:
            neighbors.append((i, j-1))
        if j < n-1:
            neighbors.append((i, j+1))
        return neighbors

    def dfs(i, j, current_path, current_sum):
        nonlocal max_average
        current_path.append(matrix[i][j])
        current_sum += matrix[i][j]
        if len(current_path) == n:
            avg = current_sum / n
            if avg > max_average:
                max_average = avg
        else:
            for x, y in get_neighbors(i, j):
                dfs(x, y, current_path, current_sum)
        current_path.pop()
        current_sum -= matrix[i][j]

    max_average = float('-inf')
    for i in range(n):
        for j in range(n):
            dfs(i, j, [], 0)
    return max_average
```

