def remove_nested(tup):
    # Initialize an empty list to store the flattened elements
    flattened = []
    # Define a recursive function to flatten the tuple
    def flatten_inner(sub_tup):
        for element in sub_tup:
            if isinstance(element, tuple):
                flatten_inner(element)
            else:
                flattened.append(element)
    # Start the recursion with the input tuple
    flatten_inner(tup)
    # Convert the list back to a tuple and return it
    return tuple(flattened)

