def remove_nested(tup):
    # Define the base case: if the tuple is a tuple of length 1 and not a nested tuple, return it
    if len(tup) == 1 and isinstance(tup, tuple) and not isinstance(tup[0], tuple):
        return tup[0]
    # Define the recursive case: if the first element is a tuple, remove the nested tuple, then recurse
    elif isinstance(tup[0], tuple):
        return remove_nested(tup[0])
    # If the first element is not a tuple, return the current element
    return tup[0] + remove_nested(tup[1:])
