def rgb_to_hsv(r, g, b):
    # Convert RGB to HSV
    max_val = max(r, g, b)
    min_val = min(r, g, b)
    diff = max_val - min_val

    if max_val == 0:
        h = 0
    elif max_val == r:
        h = (60 * ((g - b) / diff) + 360) % 360
    elif max_val == g:
        h = (60 * ((b - r) / diff) + 120) % 360
    elif max_val == b:
        h = (60 * ((r - g) / diff) + 240) % 360

    s = (diff / max_val) * 100 if max_val != 0 else 0
    v = max_val * 100

    return (h, s, v)
```

