def rgb_to_hsv(r, g, b):
    def max_min(x, y, z):
        return (max(x, y, z), min(x, y, z))

    r, g, b = r / 255.0, g / 255.0, b / 255.0
    cmax, cmin = max_min(r, g, b)
    delta = cmax - cmin

    if delta == 0:
        hue = 0
    elif cmax == r:
        hue = (60 * ((g - b) / delta) % 6)
    elif cmax == g:
        hue = (60 * ((b - r) / delta) + 120)
    else:
        hue = (60 * ((r - g) / delta) + 240)

    if cmax == 0:
        saturation = 0
    else:
        saturation = (delta / cmax) * 100

    value = cmax * 100

    return hue, saturation, value
