import math

def rgb_to_hsv(r, g, b):
    max_color = max(r, g, b)
    min_color = min(r, g, b)
    diff = max_color - min_color

    value = max_color / 255.0

    if diff == 0:
        hue = 0
    elif max_color == r:
        hue = (60.0 * ((g - b) / diff)) % 360.0
    elif max_color == g:
        hue = (60.0 * ((b - r) / diff)) + 120.0
    else:
        hue = (60.0 * ((r - g) / diff)) + 240.0

    saturation = (value == 0) and 0 or (diff / value) * 100.0

    return (hue, saturation, value)
