def rencontres_number(n, k):
    # Initialize the first two rencontres numbers
    if n == 0:
        return 1
    elif n == 1:
        return 1
    # Calculate the nth rencontres number using the recurrence relation
    else:
        a, b = 1, 1
        for _ in range(2, n + 1):
            a, b = b, (a + b) // k + (b * (n - a + 1)) // k
        return b
