def rencontres_number(n, r):
    # Base case: only one way to arrange r people in n positions
    if r == 0:
        return 1
    # Recursive case: sum ofplacing r-1 people in (n-1) positions and r places in n positions
    return (n - r + 1) * rencontres_number(n - 1, r - 1)
