import heapq

def nth_super_ugly_number(n, primes):
    heap = []
    for p in primes:
        heapq.heappush(heap, (p, p))
    uglies = set()
    current = 0
    while len(uglies) < n:
        current, prime = heapq.heappop(heap)
        uglies.add(current)
        for p in primes:
            if p != prime:
                heapq.heappush(heap, (p, current * p))
    return current
