def min_sum_path(triangle):
    # Update the triangle in-place to store the minimum path sum to each position
    for i in range(1, len(triangle)):
        for j in range(len(triangle[i])):
            # To each position, add the minimum of the two paths from the position above it
            triangle[i][j] += min(triangle[i-1][j], triangle[i-1][j+1])
    # The bottom right position will contain the minimum path sum
    return triangle[-1][-1]
