def min_sum_path(triangle):
    n = len(triangle)
    for i in range(1, n):
        triangle[i][0] += triangle[i-1][0]
        triangle[i][i] += triangle[i-1][i-1]
        for j in range(1, i):
            triangle[i][j] += min(triangle[i-1][j], triangle[i-1][j-1])
    return min(triangle[n-1])
```

