def n_common_words(text, n):
    # Split the text into words
    words = text.split()
    # Count the occurrences of each word
    word_count = {}
    for word in words:
        if word in word_count:
            word_count[word] += 1
        else:
            word_count[word] = 1
    # Sort the word count dictionary by value in descending order
    sorted_word_count = sorted(word_count.items(), key=lambda x: x[1], reverse=True)
    # Return the top n most common words
    return sorted_word_count[:n]
```

