def join_tuples(tuples_list):
    result = []
    # Find the common initial element
    common_start = tuples_list[0][0]
    for t in tuples_list:
        if t[0] != common_start:
            break
    else:
        # If all tuples have the same initial element
        result.append(tuples_list[0])
        return result

    for t in tuples_list:
        if t[0] == common_start:
            result.append(tuple(t[i] for i in range(1, len(t))))

    return result
