def join_tuples(tup_list):
    # Create an empty dictionary to store initial elements and their corresponding tuples
    result = {}
    for tup in tup_list:
        # Get the initial element of the tuple
        key = tup[0]
        # Append the tuple to the list of tuples associated with the initial element
        if key in result:
            result[key].append(tup)
        else:
            result[key] = [tup]

    # Combine the lists of tuples into a single list of tuples with similar initial elements
    final_result = []
    for key, values in result.items():
        final_result.extend(values)

    return final_result

