def Total_Hamming_Distance(n):
    total_distance = 0
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            total_distance += hamming_distance(i, j)
    return total_distance

def hamming_distance(x, y):
    distance = 0
    while x > 0 or y > 0:
        if x % 2 != y % 2:
            distance += 1
        x = x // 2
        y = y // 2
    return distance

