def radix_sort(arr):
    if not arr or len(arr) <= 1:
        return arr
    base = 10
    max_value = max(arr)
    positions = []

    while max_value >= base:
        positions.append([0] * base)
        max_value //= base

    for i in range(len(arr)):
        index = arr[i] // positions[0]
        positions[0][index] += 1

    sorted_arr = []
    for pos in positions:
        for count, num in enumerate(pos):
            for _ in range(num):
                sorted_arr.append(count * positions[0][num] * base + arr[i])
                i += 1

    return sorted_arr
```

