def check_Type_Of_Triangle(a, b, c):
    # Sort the sides to make it easier to determine the type of triangle
    sides = sorted([a, b, c])
    # Check for the type of triangle based on the sides
    if sides[2] ** 2 > sides[0] ** 2 + sides[1] ** 2:
        return "Obtuse-angled Triangle"
    elif sides[2] ** 2 == sides[0] ** 2 + sides[1] ** 2:
        return "Right-angled Triangle"
    else:
        return "Acute-angled Triangle"
