def check(arr, n):
    # Find the index where sorting starts
    start = 0
    for i in range(1, n):
        if arr[i] < arr[i - 1]:
            start = i
            break

    # Check if all elements after the start index are sorted correctly
    for i in range(start + 1, n):
        if arr[i] < arr[i - 1]:
            return False

    # Check if all elements before the start index are in descending order and the last element is greater than the first
    if start == 0:
        return True
    for i in range(start):
        if arr[i] < arr[i - 1]:
            return False
    return arr[-1] > arr[0]
```

