def mul_even_odd(numbers):
    even_product = 1
    odd_product = 1
    has_even = False
    has_odd = False

    for num in numbers:
        if num % 2 == 0:
            even_product *= num
            has_even = True
        else:
            odd_product *= num
            has_odd = True

    if has_even and has_odd:
        return even_product * odd_product
    else:
        return None  # Return None if there are no even or odd numbers in the list
