def catalan_number(n):
    # Base case: the first two Catalan numbers
    if n <= 1:
        return 1
    # Recursive case: catalan(n) = (2n)! / ((n+1)!n!)
    else:
        return (n * catalan_number(n-1) + catalan_number(n-2)) // (n + 1)
```

