def catalan_number(n):
    # Base case: the first two Catalan numbers are 1 and 1
    if n == 0 or n == 1:
        return 1
    # Recursive case: C(n) = C(n-1) * (2n - 1) / (n + 1)
    else:
        return catalan_number(n-1) * (2*n - 1) // (n + 1)
