def sum_of_primes_divisors(num):
    def is_prime(n):
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    prime_sum = 0
    for i in range(2, num + 1):
        while num % i == 0 and is_prime(i):
            prime_sum += i
            num //= i
    return prime_sum

