    while start <= end:
        mid = (start + end) // 2
        if arr[mid] == target:
            if mid == end or arr[mid + 1] > target:
                return mid
            start = mid + 1
        elif arr[mid] < target:
            start = mid + 1
        else:
            end = mid - 1
    return -1
