def maximum_segments(n, a, b, c):
    max_segments = 0  # Initialize maximum segments to 0
    if a <= n:
        max_segments += n // a  # Calculate maximum segments from length a
    if b <= n:
        max_segments += n // b  # Calculate maximum segments from length b
    if c <= n:
        max_segments += n // c  # Calculate maximum segments from length c
    return max_segments
