    # Iterate through possible segments using the least common multiple (LCM)
    for i in range(1, n + 1):
        if (i % a == 0 and i % b == 0) or (i % a == 0 and i % c == 0) or (i % b == 0 and i % c == 0):
            count += 1
    return count
