def count_duplic(nums):
    if not nums:
        return ([], [])

    count_list = []
    duplicate_list = []
    current_count = 1

    for i in range(1, len(nums)):
        if nums[i] == nums[i - 1]:
            current_count += 1
        else:
            count_list.append(current_count)
            duplicate_list.append(nums[i - 1])
            current_count = 1

    count_list.append(current_count)
    duplicate_list.append(nums[-1])

    return (duplicate_list, count_list)

