def find_kth(arr1, arr2, k1, k2, k):
    if k1 == 0:
        return arr2[k2 - 1]
    if k2 == 0:
        return arr1[k1 - 1]
    if k == 1:
        return min(arr1[k1 - 1], arr2[k2 - 1])

    mid1 = arr1[k1 // 2 - 1] if k1 // 2 - 1 >= 0 else float('-inf')
    mid2 = arr2[k2 // 2 - 1] if k2 // 2 - 1 >= 0 else float('-inf')

    if mid1 <= mid2:
        if k1 + k2 - 1 >= k:
            return find_kth(arr1[:k1], arr2, k1, k2 - (k1 - k), k)
        else:
            return find_kth(arr1[k1:], arr2[:k2], k1 - (k - k2), k2, k)
    else:
        if k1 + k2 - 1 >= k:
            return find_kth(arr1, arr2[:k2], k1, k2 - (k1 - k), k)
        else:
            return find_kth(arr1[:k1], arr2[k2:], k1 - (k - k2), k2, k)
