def find_longest_conseq_subseq(arr, n):
    # Sort the array to make consecutive elements adjacent
    arr.sort()
    longest_subseq_len = 1
    curr_subseq_len = 1

    # Iterate through the sorted array to find the longest consecutive subsequence
    for i in range(1, n):
        if arr[i] == arr[i - 1] + 1:
            curr_subseq_len += 1
        else:
            longest_subseq_len = max(longest_subseq_len, curr_subseq_len)
            curr_subseq_len = 1

    # Return the length of the longest consecutive subsequence
    return max(longest_subseq_len, curr_subseq_len)
