    max_num = max(nums)
    second_max_num = min(nums)

    # Iterate through the array to find the actual maximum and second maximum products
    for num in nums:
        if num > max_num:
            second_max_num = max_num
            max_num = num
        elif num > second_max_num and num != max_num:
