def removals(arr, k, min_diff):
    arr.sort()  # Sort the array to make it easier to find the minimum removals
    n = len(arr)
    removals_count = 0

    for i in range(n - 1):
        if arr[i + 1] - arr[i] <= min_diff:
            continue
        else:
            removals_count += i + 1  # All elements after arr[i] up to arr[i + 1] would need to be removed
            break

    if removals_count < n - 1:
        removals_count += n - (removals_count + 1)  # Adjust if the loop didn't fully remove all elements
    return removals_count
