def find_Points(start1, end1, start2, end2):
    # Ensure start1 is always less than or equal to start2
    if start1 > start2:
        start1, start2 = start2, start1

    # Ensure end1 is always greater than or equal to end2
    if end1 < end2:
        end1, end2 = end2, end1

    # Calculate the starting and ending points for the unique range
    unique_start = max(start1, start2)
    unique_end = min(end1, end2)

    return (unique_start, unique_end)
