def find_Points(max1, min1, max2, min2):
    # Ensure the first range is smaller
    if max2 < min1:
        max1, max2 = max2, min1
        min1, min2 = min2, max1

    # Choose a point within the first range and outside the second range
    point = max1 + 1
    while min2 <= point <= max2:
        point += 1

    return (min1, point - 1)
