def get_median(nums1, nums2, n):
    # Ensure nums1 is the smaller array
    if n < len(nums2):
        nums1, nums2 = nums2, nums1
        n = len(nums2)

    low, high = 0, n
    while low <= high:
        i = (low + high) // 2
        j = (n + low + high) // 2

        L1 = nums1[i] if i < n else float('-inf')
        L2 = nums2[j] if j < n else float('-inf')
        R1 = nums1[i + 1] if i < n - 1 else float('inf')
        R2 = nums2[j + 1] if j < n - 1 else float('inf')

        if L1 <= R2 and L2 <= R1:
            if n % 2 == 1:
                return max(L1, L2)
            else:
                return (max(L1, L2) + min(R1, R2)) / 2
        elif L1 > R2:
            high = i - 1
        else:
            low = i + 1
    return 0.0  # In case there's an error in the input arrays
```

