def min_coins(coins, n, total):
    # Initialize a list to store the minimum number of coins for each value from 0 to total
    dp = [ float('inf')] * (total + 1)
    dp[0] = 0  # Base case: 0 coins are needed to make value 0

    # Update the minimum coins for each value from 1 to total
    for i in range(1, total + 1):
        for coin in coins:
            if i >= coin:
                dp[i] = min(dp[i], dp[i - coin] + 1)

    return dp[total] if dp[total] != float('inf') else -1
