def min_coins(coins, amount, target):
    if amount == target:
        return 0
    if amount > target:
        return float('inf')
    min_coin_count = float('inf')
    for coin in coins:
        new_count = 1 + min_coins(coins, amount + coin, target)
        if new_count < min_coin_count:
            min_coin_count = new_count
    return min_coin_count
