```python
def get_Pairs_Count(arr, n, sum):
    count = 0
    arr.sort()
    for i in range(0, n-1):
        low = i + 1
        high = n - 1
        while low < high:
            current_sum = arr[i] + arr[low] + arr[high]
            if current_sum == sum:
                count += 1
                low += 1
                high -= 1
            elif current_sum < sum:
                low += 1
            else:
                high -= 1
    return count
```

