def substract_elements(tuple1, tuple2):
    result = ()
    for sub_tuple1, sub_tuple2 in zip(tuple1, tuple2):
        sub_result = ()
        for elem1, elem2 in zip(sub_tuple1, sub_tuple2):
            sub_result += (elem1 - elem2,),
        result += (sub_result,)
    return result
```

